import{_ as e,o as r,c as o,a2 as t}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Mundo vivo","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/world/living-world.md","filePath":"es/guide/world/living-world.md"}'),i={name:"es/guide/world/living-world.md"};function s(n,a,d,l,c,u){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="living-world" tabindex="-1">Mundo vivo <a class="header-anchor" href="#living-world" aria-label="Enlace permanente a &quot;Mundo vivo&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No implementado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Interpreta el terreno, los materiales y el clima antes de actuar.</li><li>Los árboles, el fuego y ciertos obstáculos podrían cambiar rutas y encuentros.</li><li>La protección, los permisos y la recuperación limitan los cambios; sus reglas siguen abiertas.</li></ul><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lo que observas</th><th>Lo que podría significar para ti</th></tr></thead><tbody><tr><td>Vegetación seca o madera húmeda</td><td>Distintas posibilidades de ignición y propagación</td></tr><tr><td>Un árbol cerca de un paso estrecho</td><td>Una fuente de madera y un posible obstáculo después de talarlo</td></tr><tr><td>Roca fracturada</td><td>Un obstáculo seleccionado y diseñado que quizá puedas despejar</td></tr><tr><td>Barro, huellas o plantas alteradas</td><td>Información para un rastreador experto</td></tr><tr><td>Lluvia, viento o cambios del suelo</td><td>Motivos para reconsiderar una ruta o preparativo</td></tr></tbody></table><h2 id="what-s-new-in-syrolands" tabindex="-1">Qué aporta Syrolands <a class="header-anchor" href="#what-s-new-in-syrolands" aria-label="Enlace permanente a &quot;Qué aporta Syrolands&quot;">​</a></h2><p>La propuesta conecta materiales, profesiones y magia mediante reacciones compartidas: el calor puede afectar a la vegetación, las herramientas pueden modificar obstáculos adecuados y las acciones pueden dejar rastros interpretables. Va más allá de un nuevo menú de recolección; la propia ruta puede formar parte de la decisión. No promete excavar sin límites, destruir cualquier cosa ni un ecosistema completamente simulado.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Antes de llevar un carro por un paso boscoso, observas un árbol dañado inclinado hacia la ruta. Un leñador experto podría evaluarlo y elegir cómo talarlo, mientras el grupo prepara una alternativa por si el paso queda bloqueado.</p><h2 id="progression-trade-offs" tabindex="-1">Progresión y decisiones <a class="header-anchor" href="#progression-trade-offs" aria-label="Enlace permanente a &quot;Progresión y decisiones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elección</th><th>Contrapartida</th></tr></thead><tbody><tr><td>Conocer los materiales y llevar herramientas adecuadas</td><td>Mejor información y más opciones, a cambio de equipo y tiempo</td></tr><tr><td>Utilizar fuego o magia ambiental</td><td>Posible valor táctico, pero la propagación y los permisos necesitan límites definidos</td></tr><tr><td>Modificar una ruta útil</td><td>Una ventaja inmediata puede afectar a otros viajeros y a la recuperación futura de recursos</td></tr></tbody></table><p>Las ciudades, viviendas y lugares emblemáticos necesitan reglas de protección distintas. La regeneración, la duración de los rastros y las posibles consecuencias de destruir siguen sin decidirse; no se presupone permiso para destruir las pertenencias de otro jugador.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/professions/lumberjacking.html">Lumberjacking</a> · <a href="/Syrolands-Public/es/guide/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/es/guide/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/es/guide/magic/overview.html">Magery</a></p><h2 id="full-design-specification" tabindex="-1">Especificación completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/living-world.html">Especificaciones de diseño: mundo vivo y materiales</a></p>',17)])])}const h=e(i,[["render",s]]);export{m as __pageData,h as default};
